using namespace std;

int main() {
    string input, line;
    {
        std::ostringstream ss;
        ss << cin.rdbuf();
        input = ss.str();
    }

    istringstream iss(input);
    int n, k;
    string s, t;
    iss >> n >> k >> s >> t;

    if (t[0] == t[1]) {
        int cnt = 0;
        for (char c : s) if (c == t[0]) cnt++;
        long long x = min((long long)(cnt + k), (long long)n);
        cout << (x * (x - 1)) / 2 << endl;
        return 0;
    }

    int N = n + 2;
    int K = k + 2;
    vector<vector<vector<double>>> f(N, vector<vector<double>>(K, vector<double>(N, -1e5)));
    f[0][0][0] = 0;

    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= k; j++) {
            for (int cnt0 = 0; cnt0 <= i; cnt0++) {
                if (f[i][j][cnt0] < 0) continue;
                int e0 = (s[i] == t[0]) ? 1 : 0;
                int e1 = (s[i] == t[1]) ? 1 : 0;

                f[i + 1][j][cnt0 + e0] = max(f[i + 1][j][cnt0 + e0], f[i][j][cnt0] + e1 * cnt0);
                f[i + 1][j + 1][cnt0 + 1] = max(f[i + 1][j + 1][cnt0 + 1], f[i][j][cnt0]);
                f[i + 1][j + 1][cnt0] = max(f[i + 1][j][cnt0], f[i][j][cnt0] + cnt0);
            }
        }
    }

    double best = -1e18;
    for (int i = 0; i <= k; i++) {
        for (int j = 0; j <= n; j++) {
            if (f[n][i][j] > best) best = f[n][i][j];
        }
    }

    cout << (long long)best << endl;
    return 0;
}
